Here’s a simple **base conversion program in C** that works **both ways**:

- **Decimal ➝ Any base (2–16)**  
- **Any base (2–16) ➝ Decimal**

All in one small, exam-friendly code.

---

### ✅ Full C Code (Beginner Friendly)

```c
#include <stdio.h>
#include <string.h>

// Convert a single digit char to its numeric value
int charToValue(char ch) {
    if (ch >= '0' && ch <= '9')
        return ch - '0';
    else if (ch >= 'A' && ch <= 'F')
        return ch - 'A' + 10;
    else if (ch >= 'a' && ch <= 'f')
        return ch - 'a' + 10;
    else
        return -1;  // invalid
}

// Convert value (0–15) to digit char
char valueToChar(int v) {
    if (v >= 0 && v <= 9)
        return '0' + v;
    else
        return 'A' + (v - 10);   // 10->A, 11->B, ...
}

// base-b string -> decimal int
int toDecimal(char num[], int base) {
    int len = strlen(num);
    int value = 0;
    int i, digit;

    for (i = 0; i < len; i++) {
        digit = charToValue(num[i]);
        if (digit < 0 || digit >= base) {
            printf("Invalid digit '%c' for base %d\n", num[i], base);
            return -1;
        }
        value = value * base + digit;
    }

    return value;
}

// decimal int -> base-b string
void fromDecimal(int num, int base, char result[]) {
    char temp[50];
    int i = 0, rem;

    if (num == 0) {
        result[0] = '0';
        result[1] = '\0';
        return;
    }

    while (num > 0) {
        rem = num % base;
        temp[i] = valueToChar(rem);
        i++;
        num = num / base;
    }

    // temp has reversed number, so reverse it into result
    int j;
    result[i] = '\0';  // end string
    for (j = 0; j < i; j++) {
        result[j] = temp[i - j - 1];
    }
    result[i] = '\0';
}

int main() {
    int choice;
    int baseFrom, baseTo;
    char numStr[50];
    int decimalValue;
    char converted[50];

    printf("1. Any base -> Decimal\n");
    printf("2. Decimal -> Any base\n");
    printf("Enter choice: ");
    scanf("%d", &choice);

    if (choice == 1) {
        printf("Enter base of given number (2–16): ");
        scanf("%d", &baseFrom);

        printf("Enter number in that base: ");
        scanf("%s", numStr);

        decimalValue = toDecimal(numStr, baseFrom);
        if (decimalValue != -1) {
            printf("Decimal value = %d\n", decimalValue);
        }
    }
    else if (choice == 2) {
        printf("Enter decimal number: ");
        scanf("%d", &decimalValue);

        printf("Enter base to convert to (2–16): ");
        scanf("%d", &baseTo);

        fromDecimal(decimalValue, baseTo, converted);
        printf("Number in base %d = %s\n", baseTo, converted);
    }
    else {
        printf("Invalid choice\n");
    }

    return 0;
}
```

---

### How it works (short and blunt):

- **Any base → Decimal**
  - Read number as **string**.
  - For each digit:  
    `value = value * base + digit_value`.
- **Decimal → Any base**
  - Repeatedly:
    - `rem = num % base`
    - store remainder
    - `num = num / base`
  - Reverse the remainders to get final answer.

If you want an even more cut-down version only for **decimal <-> binary** or **one direction**, say so and I’ll strip this down further.

Alright — **no nonsense, shortest beginner-friendly version**.  
Just **2 functions**:

- `decToBase()` → Decimal → Any base  
- `baseToDec()` → Any base → Decimal  

No fancy validation, no extra features.

---

## ✅ Simplest C Code

```c
#include <stdio.h>
#include <string.h>

void decToBase(int num, int base) {
    int rem, i = 0;
    char res[50];

    if (num == 0) {
        printf("0");
        return;
    }

    while (num > 0) {
        rem = num % base;
        if (rem < 10)
            res[i] = rem + '0';
        else
            res[i] = rem - 10 + 'A';
        num /= base;
        i++;
    }

    // reverse for correct order
    for (i = i - 1; i >= 0; i--)
        printf("%c", res[i]);
}

int baseToDec(char num[], int base) {
    int value = 0, digit;
    for (int i = 0; num[i] != '\0'; i++) {
        if (num[i] >= '0' && num[i] <= '9')
            digit = num[i] - '0';
        else
            digit = num[i] - 'A' + 10;
        value = value * base + digit;
    }
    return value;
}

int main() {
    int choice;
    printf("1. Any base -> Decimal\n");
    printf("2. Decimal -> Any base\n");
    scanf("%d", &choice);

    if (choice == 1) {
        char num[50];
        int base;
        printf("Enter number: ");
        scanf("%s", num);
        printf("Enter base: ");
        scanf("%d", &base);
        printf("Decimal = %d", baseToDec(num, base));
    }
    else {
        int num, base;
        printf("Enter decimal number: ");
        scanf("%d", &num);
        printf("Enter base: ");
        scanf("%d", &base);
        printf("Converted = ");
        decToBase(num, base);
    }

    return 0;
}
```

